function sheet(t,body,action){return `<div class=sheet-page>${h(t,'',`<button class=text-button data-route=settings-main>${action==='Done'?'Done':'Cancel'}</button>`)}${body}${action!=='Done'?b(action,'settings-main','primary'):''}</div>`}
function overlay(o,s=cur){if(!o)return '';if(o==='complete'){let c=completionCards[s.variant||0];return `<div class=sheet-scrim><section class=completion-overlay><img class=gym-illustration src="${c[0]}" alt="Original bundled gym illustration"><h3>${c[1]}</h3><p>${c[2]}</p>${b('Done','today-completed','primary')}</section></div>`}if(['todayMenu','exercise','set','workout'].includes(o)){let a=o==='workout'?[['Copy workout','copy-workout'],['Repeat workout','repeat-workout'],['Delete workout','program-delete-workout']]:o==='todayMenu'?[['Skip exercise','today-skipped']]:o==='set'?[['Edit set','program-set-editor'],['Move set','program-reorder'],['Delete set','program-delete-confirm']]:[['Edit exercise','program-edit'],['Move exercise','program-reorder'],['Delete exercise','program-delete-exercise']];return `<div class=menu-scrim><section class=context-menu>${a.map(x=>`<button class="${x[0].startsWith('Delete')?'is-destructive':''}" data-route=${x[1]}>${x[0]}</button>`).join('')}<button data-route=${o==='todayMenu'?'today-partial':'program-edit'}>Cancel</button></section></div>`}if(o.startsWith('del')){let x=o==='delWorkout'?'workout':o==='delAccount'?'account':o==='delExercise'?'exercise':'set';return `<div class=sheet-scrim><section class=alert-card><span class=error-symbol>!</span><h3>Delete ${x}?</h3><p>This permanently deletes ${x==='workout'?'the workout and all of its sets':x==='account'?'your account and workout data':'this '+x}.</p><div>${b('Cancel',x==='account'?'settings-main':'program-edit')}${b('Delete '+x,x==='account'?'settings-main':'program-edit','destructive')}</div></section></div>`}let actual=o==='actual',unit=s.unit||unitPref,returnRoute=s.id.startsWith('today')?'today-partial':s.v==='history'?'program-history':'program-edit',fields=s.type==='timed'?[['Time (sec)','45','number']]:s.type==='reps'?[['Reps','12','number']]:[['Reps','8','number'],['Weight ('+unit+')',unit==='lb'?'132':'60','number']],note=actual?'Actual result stays completed.':s.preserveActual?'Plan update keeps the recorded actual intact.':'Planned values before completion.';return `<div class=sheet-scrim><section class=sheet><header><button data-route=${returnRoute}>Cancel</button><h3>${actual?'Edit actual':'Edit plan'}</h3><button class=accent-action data-route=${returnRoute}>Save</button></header><p>${note}</p>${form(fields)}</section></div>`}
function auth(s){let signup=s.id==='auth-sign-up',reset=s.id==='auth-reset',title=reset?'Reset password':signup?'Create account':'Welcome back',copy=reset?'Enter your email to receive a reset link.':signup?'Build your program and start checking off sets.':'Your workout is ready when you are.',fields=reset?[['Email','you@example.com']]:[['Email','you@example.com'],['Password','••••••••']],action=reset?'Send reset link':signup?'Create account':'Sign in';return `<section class=auth-screen><div class=auth-mark>✓</div><h2>${title}</h2><p>${copy}</p>${form(fields)}${b(action,reset?'auth-sign-in':'today-incomplete','primary')}${!reset?`<button class=text-button data-route=auth-reset>Forgot password?</button><div class=auth-divider>or</div><button class=google-button>G Continue with Google</button><button class=text-button data-route=${signup?'auth-sign-in':'auth-sign-up'}>${signup?'Already have an account? Sign in':'Create account'}</button>`:`<button class=text-button data-route=auth-sign-in>Back to sign in</button>`}</section>`}
function render(s=cur,target=A){let out=s.id.startsWith('today')?today(s):s.id.startsWith('program')?program(s):['picker','custom','copy','repeat'].includes(s.v)?flow(s):s.id.startsWith('settings')?settings(s):s.id.startsWith('auth')?auth(s):s.v==='loading'?h('Today')+'<section class=empty-state><span class=spinner></span><p>Loading your workout</p></section>':h('Program')+'<section class=alert-card><span class=error-symbol>!</span><h3>Couldn’t load program</h3></section>';target.innerHTML=out;if(target===A){let shell=A.closest('.phone-shell'),old=shell&&shell.querySelector('.system-tab-bar'),focused=s.id.startsWith('auth')||['profile','weight'].includes(s.v);if(focused&&old)old.remove();else if(!focused&&old)old.outerHTML=tabHtml(s);else if(!focused&&!old)shell.insertAdjacentHTML('beforeend',tabHtml(s))}}
function go(id){let x=S.find(s=>s.id===id);if(x){cur=x;gallery=0;document.body.classList.remove('is-gallery');B.setAttribute('aria-pressed','false');render();P.value=id}}
function trigger(s){const paths={'today-partial':'Today → tap any set','today-completed':'Today → complete every remaining set','today-exercise-menu':'Today → exercise •••','today-skipped':'Today → exercise ••• → Skip exercise','today-rest-day':'Today → no workout scheduled today','today-no-program':'Today → no workouts exist','today-set-editor':'Today → press and hold incomplete set','today-set-editor-actual':'Today → press and hold completed set','today-set-editor-lb':'Settings → Weight unit lb → Today → press and hold set','today-set-editor-actual-lb':'Settings → Weight unit lb → Today → press and hold completed set','today-completion':'Today → final required set','today-completion-barely':'Today → final required set → bundled variant','today-completion-another':'Today → final required set → bundled variant','program-week-prev':'Program → Week → Previous week','program-week-next':'Program → Week → Next week','program-month-prev':'Program → Month → Previous month','program-month-next':'Program → Month → Next month','program-edit':'Program → select current date','program-history-week-prev':'Program → previous week → select past date','program-edit-week-next':'Program → next week → select planned date','program-history-month-prev':'Program → previous month → select past date','program-edit-month-next':'Program → next month → select planned date','program-add-set':'Program → Bench Press → Add set','program-add-timed-set':'Program → Plank → Add set','program-set-editor':'Program → select planned set','program-completed-plan-editor':'Program → completed set → Edit plan','program-reorder':'Program → Set or exercise ••• → Move','program-set-editor-lb':'Settings → Weight unit lb → Program → select set','program-exercise-menu':'Program → Bench Press → •••','program-set-menu':'Program → Set 2 → •••','program-workout-menu':'Program → workout •••','program-delete-confirm':'Program → Set 2 ••• → Delete set','program-delete-exercise':'Program → Bench Press ••• → Delete exercise','program-delete-workout':'Program → workout ••• → Delete workout','program-history':'Program → Week or Month → select Sep 7 past date','program-history-set-editor':'Program → past date → select actual set','program-history-set-editor-lb':'Settings → Weight unit lb → past actual set','exercise-picker':'Program → Add exercise','custom-exercise':'Exercise picker → Add custom exercise','copy-workout':'Program → workout ••• → Copy workout','copy-workout-calendar':'Copy workout → Destination date','repeat-workout':'Program → workout ••• → Repeat workout','repeat-workout-until':'Repeat workout → Until date','repeat-workout-calendar':'Repeat workout → Until date → date picker','settings-profile':'Settings → Profile','settings-body-weight':'Settings → Body weight','settings-appearance':'Settings → Appearance inline control','settings-unit':'Settings → Weight unit inline control','settings-account':'Settings → Danger zone → Delete account','state-loading':'Today → loading state','state-offline':'Today → cached offline state','state-error':'Program → load error','state-disabled':'Settings → destructive disabled state'};return paths[s.id]||'Top-level route'}
document.addEventListener('click',e=>{let a=e.target.closest('[data-appearance]'),u=e.target.closest('[data-unit]'),shift=e.target.closest('[data-calendar-shift]');if(a){document.documentElement.dataset.theme=a.dataset.appearance==='system'?'light':a.dataset.appearance;a.parentElement.querySelectorAll('button').forEach(x=>{x.setAttribute('aria-pressed',x===a);x.classList.toggle('is-selected',x===a)})}if(u){unitPref=u.dataset.unit;u.parentElement.querySelectorAll('button').forEach(x=>{x.setAttribute('aria-pressed',x===u);x.classList.toggle('is-selected',x===u)});render()}if(shift)shift.parentElement.querySelector('strong').textContent=shift.dataset.calendarShift});
