let holdTimer;document.addEventListener('pointerdown',e=>{let set=e.target.closest('[data-set]');if(set)holdTimer=setTimeout(()=>go(set.dataset.editor),600)});['pointerup','pointercancel','pointerleave'].forEach(type=>document.addEventListener(type,()=>clearTimeout(holdTimer)));document.addEventListener('keydown',e=>{let set=e.target.closest('[data-set]');if(set&&(e.key==='ContextMenu'||(e.shiftKey&&e.key==='Enter'))){e.preventDefault();go(set.dataset.editor)}});document.addEventListener('click',e=>{if(e.target.closest('[data-set]'))return;let x=e.target.closest('[data-route]');if(x)go(x.dataset.route);let t=e.target.closest('[data-tab]');if(t)go(t.dataset.tab==='today'?'today-partial':t.dataset.tab==='program'?'program-week':'settings-main')});document.addEventListener('contextmenu',e=>{let set=e.target.closest('[data-set]');if(set){e.preventDefault();go(set.dataset.editor)}});document.addEventListener('input',e=>{if(e.target.matches('.search input')){q=e.target.value;render()}});P.onchange=()=>go(P.value);document.querySelectorAll('[data-theme-choice]').forEach(x=>x.onclick=()=>{document.documentElement.dataset.theme=x.dataset.themeChoice;document.querySelectorAll('[data-theme-choice]').forEach(y=>y.setAttribute('aria-pressed',y===x))});B.onclick=()=>{gallery=!gallery;document.body.classList.toggle('is-gallery',gallery);B.setAttribute('aria-pressed',gallery);if(gallery){G.innerHTML=`<div class=gallery>${S.map(s=>`<article class=gallery-card><header><p>${s.group}</p><h2>${s.label}</h2><small>Trigger: ${trigger(s)}</small></header><section class="phone-shell gallery-phone"><div class=system-status>9:41　● ● ●</div><div class=app-content></div>${(s.id.startsWith('auth')||['profile','weight'].includes(s.v))?'':tabHtml(s)}</section></article>`).join('')}</div>`;G.querySelectorAll('.app-content').forEach((x,i)=>render(S[i],x))}};render();
